 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and grid[r + 1][c2] == color:
                    rr, cc = r + 1, c2
                    while 0 <= rr + 1 < h and 0 <= cc + dc < w:
                        rr += 1
                        cc += dc
                        out[rr][cc] = color
    return out
